const TArray<FWireSegment>& AFoil1111WireframeActor::Segments() { return GSegments; }

AFoil1111WireframeActor::AFoil1111WireframeActor() { PrimaryActorTick.bCanEverTick = true; }

void AFoil1111WireframeActor::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);
    const FTransform& X = GetActorTransform();
    for (const FWireSegment& S : GSegments)
    {
        DrawDebugLine(GetWorld(), X.TransformPosition(S.A), X.TransformPosition(S.B),
                      LineColor, false, -1.f, 0, LineThickness);
    }
}
